  const badge = d <= 0 ? { t: "Hari ini", c: "emerald" } : d === 1 ? { t: "Kemarin", c: "amber" } : d <= 7 ? { t: "Minggu ini", c: "blue" } : d <= 31 ? { t: "Bulan ini", c: "blue" } : { t: "Lama", c: "slate" };
