              {qMsg && <p className={`text-xs ${qMsg.t === "ok" ? "text-emerald-500" : "text-rose-500"}`}>{qMsg.m}</p>}
              <Btn onClick={simpanQ} className="w-full">Simpan pertanyaan</Btn>
