  const delUser = (id, name) => { if (window.confirm(`Hapus anggota "${name}"? Tindakan ini permanen.`)) { update((s) => { s.users = s.users.filter((x) => x.id !== id); return s; }); taskOps.delByUser(id); } }; // task anggota dihapus dari tabel `tasks`
