/* ============ Arsip (motor terjual, riwayat inspeksi, absen harian) ============ */
function ArsipTab({ state, me, update, unitOps }) {
  const isMgr = me.role === "owner" || me.role === "admin";
  const [sub, setSub] = useState("terjual");
  const [detail, setDetail] = useState(null);
  const [expModal, setExpModal] = useState(null);
  const [openInspection, setOpenInspection] = useState(null);
  const [soldShow, setSoldShow] = useState(20);
  const [inspShow, setInspShow] = useState(20);
  const [ymAbsen, setYmAbsen] = useState(month());
  const sold = [...state.units].filter((u) => u.status === "terjual").sort((a, b) => (b.soldAt || "").localeCompare(a.soldAt || ""));
  // Rekap per bulan untuk header grup di daftar "Motor Terjual": jumlah, modal, omzet, profit,
  // dan total balik modal investor (modal + jatah profit, hanya unit ber-investor).
  const soldMonthAgg = {};
  for (const u of sold) {
    const mk = (u.soldAt || "").slice(0, 7) || "—";
    const g = soldMonthAgg[mk] || { count: 0, modal: 0, revenue: 0, profit: 0, invPayback: 0 };
    const modal = u.buyPrice + expByUnit(state, u.id); const p = unitProfit(state, u);
    g.count++; g.modal += modal; g.revenue += u.sellPrice || 0; g.profit += (u.sellPrice || 0) - modal;
    if (u.investorCode && p && p.share > 0) g.invPayback += modal + p.investorCut;
    soldMonthAgg[mk] = g;
  }
  const inspected = state.inspections || [];
  const dateLabel = (d) => d ? new Date(d + "T00:00:00").toLocaleDateString("id-ID", { day: "numeric", month: "short", year: "numeric" }) : "-";
  return (
    <div className="space-y-3 pt-1">
      <p className="font-bold text-lg pt-1">Arsip</p>
      <div className={`grid ${isMgr ? "grid-cols-3" : "grid-cols-2"} gap-1 s-soft rounded-xl p-1`}>
        <button onClick={() => setSub("terjual")} className={`py-2 rounded-lg text-xs font-bold transition ${sub === "terjual" ? "ac-bg text-white" : "s-muted"}`}>Motor Terjual ({sold.length})</button>
        <button onClick={() => setSub("diinspeksi")} className={`py-2 rounded-lg text-xs font-bold transition ${sub === "diinspeksi" ? "ac-bg text-white" : "s-muted"}`}>Motor Diinspeksi ({inspected.length})</button>
        {isMgr && <button onClick={() => setSub("absen")} className={`py-2 rounded-lg text-xs font-bold transition ${sub === "absen" ? "ac-bg text-white" : "s-muted"}`}>Absen</button>}
      </div>
      {sub === "terjual" && (
        <div className="space-y-2">
          {sold.length === 0 && <p className="text-center text-sm s-muted py-8">Belum ada motor terjual.</p>}
          {(() => { let lastMk = null; return sold.slice(0, soldShow).map((u) => {
            const profit = (u.sellPrice || 0) - u.buyPrice - expByUnit(state, u.id);
            const mk = (u.soldAt || "").slice(0, 7) || "—"; const showHeader = mk !== lastMk; lastMk = mk; const agg = soldMonthAgg[mk] || { count: 0, modal: 0, revenue: 0, profit: 0, invPayback: 0 };
            return (
              <React.Fragment key={u.id}>
              {showHeader && (
                <div className="px-1 pt-2.5 pb-0.5">
                  <p className="text-xs font-bold s-muted flex items-center gap-1.5">{mk === "—" ? "Tanpa tanggal" : monthLabel(mk)} · {agg.count} motor{mk === month() && <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-emerald-500 text-white">Bulan ini</span>}</p>
                  {isMgr && <p className="text-[10px] s-muted mt-0.5 leading-relaxed">Modal {rp(agg.modal)} · Omzet {rp(agg.revenue)} · Profit <span className={agg.profit >= 0 ? "text-emerald-500" : "text-rose-500"}>{rp(agg.profit)}</span>{agg.invPayback > 0 && <> · Balik modal investor <span className="ac-text">{rp(agg.invPayback)}</span></>}</p>}
                </div>
              )}
              <Card className="p-3">
                <div className="flex items-center gap-3 cursor-pointer active:scale-[0.99] transition" onClick={() => setDetail(u.id)}>
                  {u.photo ? <img src={u.photo} className="w-12 h-12 rounded-lg object-cover shrink-0" alt="" /> : <div className="w-12 h-12 rounded-lg s-soft grid place-items-center shrink-0"><Bike size={18} className="s-muted" /></div>}
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-semibold truncate">{u.name}</p>
                    <p className="text-[11px] s-muted">{u.plate ? u.plate + " · " : ""}Terjual {dateLabel(u.soldAt)}{u.soldBy && (state.users.find((x) => x.id === u.soldBy) || {}).name ? " · oleh " + state.users.find((x) => x.id === u.soldBy).name : ""}</p>
                  </div>
                  <div className="text-right shrink-0">
                    <p className="text-sm font-bold">{rp(u.sellPrice || 0)}</p>
                    {canSeeProfit(me, u) ? (
                      <p className={`text-[10px] font-semibold ${profit >= 0 ? "text-emerald-500" : "text-rose-500"}`}>{profit >= 0 ? "+" : ""}{rp(profit)}</p>
                    ) : (
                      <p className="text-[10px] font-semibold s-muted flex items-center gap-1 justify-end" title="Profit cuma bisa dilihat owner/admin & inspektur motor ini"><Lock size={10} />—</p>
                    )}
                  </div>
                </div>
              </Card>
              </React.Fragment>
            );
          }); })()}
          {sold.length > soldShow && <Btn variant="ghost" onClick={() => setSoldShow((n) => n + 20)} className="w-full">Tampilkan lebih ({sold.length - soldShow} lagi)</Btn>}
        </div>
      )}
      {sub === "diinspeksi" && (
        <div className="space-y-2">
          {inspected.length === 0 && <p className="text-center text-sm s-muted py-8">Belum ada riwayat inspeksi.</p>}
          {inspected.slice(0, inspShow).map((h) => {
            const unit = h.unitId && state.units.find((u) => u.id === h.unitId);
            return (
              <Card key={h.id} className="p-3">
                <div className="flex items-center gap-3 cursor-pointer active:scale-[0.99] transition" onClick={() => setOpenInspection(h)}>
                  {h.notePhotos && h.notePhotos.length > 0 ? <img src={h.notePhotos[0]} className="w-12 h-12 rounded-lg object-cover shrink-0" alt="" /> : <div className="w-12 h-12 rounded-lg s-soft grid place-items-center shrink-0"><ClipboardCheck size={18} className="s-muted" /></div>}
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-semibold truncate">{unit ? unit.name : (h.name || "Motor (tanpa nama)")}</p>
                    <p className="text-[11px] s-muted">{h.byName || "?"} · {dateLabel(h.date)}</p>
                  </div>
                  <Tag color={h.decision === "beli" ? "emerald" : "rose"}>{h.decision === "beli" ? "Dibeli" : "Tidak"}</Tag>
                </div>
              </Card>
            );
          })}
          {inspected.length > inspShow && <Btn variant="ghost" onClick={() => setInspShow((n) => n + 20)} className="w-full">Tampilkan lebih ({inspected.length - inspShow} lagi)</Btn>}
        </div>
      )}
      {isMgr && sub === "absen" && <ArsipAbsenView state={state} ym={ymAbsen} setYm={setYmAbsen} />}
      <UnitDetailModal unitId={detail} state={state} me={me} onClose={() => setDetail(null)} update={update} unitOps={unitOps} onAddExp={(id) => setExpModal({ mode: "add", unitId: id })} onEditExp={(e) => setExpModal({ mode: "edit", unitId: e.unitId, expense: e })} />
      <ExpenseModal data={expModal} units={state.units} me={me} onClose={() => setExpModal(null)} update={update} />
      <InspectionDetailModal inspection={openInspection} state={state} me={me} update={update} onClose={() => setOpenInspection(null)} />
    </div>
  );
}
// Arsip Absen — riwayat kehadiran per hari dalam sebulan. Owner/admin saja (digerbangi dari
